const found = ($input.first().json.data || [])[0] || {};
const pre = $('Номер телефону').first().json.dv || {};
const junk = s => !s || /^(test|тест|тестовий|asd|qwe|фів|уцк|green zone)/i.test(String(s).trim());
// тестовий / сміттєвий лід (імʼя або компанія) вважаємо відсутнім — агент говорить як з новим клієнтом
const lead = (junk(found.First_Name) && junk(found.Last_Name)) || junk(found.Company) ? {} : found;
const first = String(lead.First_Name || pre.name || '').trim().split(' ')[0];
const name = junk(first) ? '' : first;
const company = lead.Company && !/^@/.test(lead.Company) ? lead.Company : (pre.company || '');
return [{ json: {
  type: 'conversation_initiation_client_data',
  dynamic_variables: {
    name: name,
    name_greeting: name ? ', ' + name : '',
    company: company || '',
    lead_id: lead.id || pre.lead_id || '',
    lead_found: lead.id ? 'так' : 'ні'
  }
} }];
